//! Tests for code generated by `#[derive(Table)]`.

use std::sync::Arc;

use supabase_client_derive::Table;
use supabase_client_query::{QueryBackend, Table as _, TypedQueryBuilder};

#[derive(Debug, Clone, serde::Deserialize, Table)]
#[table(name = "logs")]
struct LogLine {
    message: String,
    level: i32,
}

#[derive(Debug, Clone, serde::Deserialize, Table)]
#[table(name = "countries")]
struct Country {
    #[primary_key]
    code: String,
    name: String,
}

#[derive(Debug, Clone, serde::Deserialize, Table)]
#[table(name = "cities")]
struct City {
    #[primary_key(auto_generate)]
    id: i32,
    name: String,
}

fn unreachable_backend() -> QueryBackend {
    QueryBackend::Rest {
        http: reqwest::Client::new(),
        // Port 9 (discard): if a request were sent it would fail with a
        // connection error, not the primary key error checked below.
        base_url: Arc::from("http://127.0.0.1:9"),
        api_key: Arc::from("anon"),
        access_token: None,
        schema: "public".into(),
    }
}

#[test]
fn derived_metadata() {
    assert!(LogLine::primary_key_columns().is_empty());
    assert_eq!(Country::primary_key_columns(), &["code"]);
    assert_eq!(Country::insertable_columns(), &["code", "name"]);
    assert_eq!(City::insertable_columns(), &["name"]);
}

/// M6: a typed update on a table without `#[primary_key]` used to send an
/// UPDATE with no WHERE clause.
#[tokio::test]
async fn update_without_primary_key_is_rejected() {
    let row = LogLine {
        message: "x".into(),
        level: 1,
    };
    let resp = TypedQueryBuilder::<LogLine>::new(unreachable_backend(), "public".into())
        .update(&row)
        .execute()
        .await;
    let err = resp.error.expect("update without a primary key must fail");
    assert!(err.to_string().contains("primary key"), "{err}");
}
